-- =====================================================================
-- DMF0082 (Fcst&Price MGMT) 전체 이관 — LOOKUP (MASTER + DETAIL) — DMF0082 편집 measure 참조
-- 사내 OCGSCMD_P01 실측 export (2026-07-21). 멱등 MERGE. 스키마 SCM_MGR.
-- =====================================================================

-- ⚠ 그리드 공유 콤보의 기타 lookup(INCOTERMS/DOM_EXP/FCST_TYPE 등)은 공유자산 — 클라우드 기존재 가정.
-- ⚠ SalesBucket 원천 DM_MST_BUCKET_CONVERSION(마스터 데이터)·FcstPriceEditMeasure 의 SCM_MST_SITE 는 마스터 — 클라우드 기존재 가정.

-- ============================================================
-- SCM_ADM_LOOKUP_MASTER  (1 rows, PK=LOOKUP_TYPE)
-- ============================================================
MERGE INTO SCM_MGR.SCM_ADM_LOOKUP_MASTER t USING (SELECT 'DM_UI_EDITABLE_MEASURE' AS LOOKUP_TYPE, 'Fcst&Price Mgmt 에서 수정 할 수 있는 Measure를 선택[INSERT_YN : 신규입력(F8)시 콤보박스 생성 여부, EDIT_YN : 수정(F2)시 수정 할 수 있는 Measure 여부,VMI_YN: INSERT시 선택한 SCMSITE가 SCM_MST_SITE에 있을시 해당 MEASURE를 포함해서 콤보박스 만들것인지에 대한 여부]' AS DESCRIPTION, 'DM' AS LOOKUP_GROUP, 'Y' AS VALID_YN, 'PROGRAM_ID' AS SEGMENT1, 'DIVISION_ID' AS SEGMENT2, 'CODE' AS SEGMENT3, 'NAME' AS SEGMENT4, '-' AS SEGMENT5, 'dsiol' AS CREATED_BY, TO_DATE('2025-02-10 14:08:03','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'dsiol' AS LAST_UPDATED_BY, TO_DATE('2025-02-14 10:11:06','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE, 'INSERT_YN' AS ATTRIBUTE1, 'EDIT_YN' AS ATTRIBUTE2, 'VMI_YN' AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, NULL AS ATTRIBUTE6, NULL AS ATTRIBUTE7, NULL AS ATTRIBUTE8, NULL AS ATTRIBUTE9, NULL AS ATTRIBUTE10, NULL AS ATTRIBUTE11, NULL AS ATTRIBUTE12, NULL AS ATTRIBUTE13, NULL AS ATTRIBUTE14, NULL AS ATTRIBUTE15 FROM DUAL) s
ON (t.LOOKUP_TYPE = s.LOOKUP_TYPE)
WHEN MATCHED THEN UPDATE SET t.DESCRIPTION = s.DESCRIPTION, t.LOOKUP_GROUP = s.LOOKUP_GROUP, t.VALID_YN = s.VALID_YN, t.SEGMENT1 = s.SEGMENT1, t.SEGMENT2 = s.SEGMENT2, t.SEGMENT3 = s.SEGMENT3, t.SEGMENT4 = s.SEGMENT4, t.SEGMENT5 = s.SEGMENT5, t.CREATED_BY = s.CREATED_BY, t.CREATION_DATE = s.CREATION_DATE, t.LAST_UPDATED_BY = s.LAST_UPDATED_BY, t.LAST_UPDATE_DATE = s.LAST_UPDATE_DATE, t.ATTRIBUTE1 = s.ATTRIBUTE1, t.ATTRIBUTE2 = s.ATTRIBUTE2, t.ATTRIBUTE3 = s.ATTRIBUTE3, t.ATTRIBUTE4 = s.ATTRIBUTE4, t.ATTRIBUTE5 = s.ATTRIBUTE5, t.ATTRIBUTE6 = s.ATTRIBUTE6, t.ATTRIBUTE7 = s.ATTRIBUTE7, t.ATTRIBUTE8 = s.ATTRIBUTE8, t.ATTRIBUTE9 = s.ATTRIBUTE9, t.ATTRIBUTE10 = s.ATTRIBUTE10, t.ATTRIBUTE11 = s.ATTRIBUTE11, t.ATTRIBUTE12 = s.ATTRIBUTE12, t.ATTRIBUTE13 = s.ATTRIBUTE13, t.ATTRIBUTE14 = s.ATTRIBUTE14, t.ATTRIBUTE15 = s.ATTRIBUTE15
WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, DESCRIPTION, LOOKUP_GROUP, VALID_YN, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15) VALUES (s.LOOKUP_TYPE, s.DESCRIPTION, s.LOOKUP_GROUP, s.VALID_YN, s.SEGMENT1, s.SEGMENT2, s.SEGMENT3, s.SEGMENT4, s.SEGMENT5, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE, s.ATTRIBUTE1, s.ATTRIBUTE2, s.ATTRIBUTE3, s.ATTRIBUTE4, s.ATTRIBUTE5, s.ATTRIBUTE6, s.ATTRIBUTE7, s.ATTRIBUTE8, s.ATTRIBUTE9, s.ATTRIBUTE10, s.ATTRIBUTE11, s.ATTRIBUTE12, s.ATTRIBUTE13, s.ATTRIBUTE14, s.ATTRIBUTE15);

